<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
$mode=$argv[1]??'--check';if(!in_array($mode,['--check','--apply'],true))throw new RuntimeException('Use --check or --apply');
$root=realpath($argv[2]??'/var/www/vhosts/shalean.com/faraios.com');
$private=realpath($argv[3]??'/var/www/vhosts/shalean.com/private/faraios-account');
if(!$root||!$private||str_starts_with($private.'/', $root.'/'))throw new RuntimeException('Invalid roots');
$payload=json_decode(gzdecode(base64_decode('',true)),true,512,JSON_THROW_ON_ERROR);
$lock=fopen($private.'/v1-007-release.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('Release locked');chmod($private.'/v1-007-release.lock',0600);
function census(string $dir):array{$out=[];foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS)) as $f){if($f->isFile()&&!$f->isLink())$out[substr($f->getPathname(),strlen($dir)+1)]=hash_file('sha256',$f->getPathname());}ksort($out);return $out;}
$before=census($root);$privateBefore=census($private);unset($privateBefore['v1-007-release.lock']);$changes=[];$drift=[];
foreach($payload as $p=>$v){if(hash('sha256',base64_decode($v['content'],true))!==$v['candidate_sha256'])throw new RuntimeException('Corrupt payload');$h=$before[$p]??null;if($h===$v['candidate_sha256'])continue;if($h!==$v['baseline_sha256'])$drift[]=$p;else $changes[]=$p;}
if($drift){echo json_encode(['status'=>'STOP','drift'=>$drift]);exit(1);}
if($mode==='--check'||!$changes){echo json_encode(['status'=>$changes?'preflight_PASS':'already_applied','files'=>5,'pending'=>count($changes),'database_writes'=>false]);exit;}
$backup=$private.'/v1-007-'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(3));if(!mkdir($backup,0700))throw new RuntimeException('Backup failed');
file_put_contents($backup.'/before.json',json_encode($before));chmod($backup.'/before.json',0600);$written=[];
try{
 foreach($changes as $p){$dest=$root.'/'.$p;if(hash_file('sha256',$dest)!==$payload[$p]['baseline_sha256'])throw new RuntimeException('Concurrent change: '.$p);$saved=$backup.'/'.str_replace('/','__',$p);if(!copy($dest,$saved)||!chmod($saved,0600))throw new RuntimeException('Backup failed');}
 foreach($changes as $p){$dest=$root.'/'.$p;$v=$payload[$p];if(hash_file('sha256',$dest)!==$v['baseline_sha256'])throw new RuntimeException('Concurrent change: '.$p);$tmp=$dest.'.v1007-'.bin2hex(random_bytes(4));$bytes=base64_decode($v['content'],true);if(file_put_contents($tmp,$bytes,LOCK_EX)!==strlen($bytes)||!chmod($tmp,fileperms($dest)&0777))throw new RuntimeException('Stage failed');if(!rename($tmp,$dest))throw new RuntimeException('Install failed');$written[]=$p;}
 $expected=$before;foreach($payload as $p=>$v)$expected[$p]=$v['candidate_sha256'];ksort($expected);if(census($root)!==$expected)throw new RuntimeException('Web census changed outside scope');
 foreach($privateBefore as $p=>$h)if(!is_file($private.'/'.$p)||hash_file('sha256',$private.'/'.$p)!==$h)throw new RuntimeException('Private file changed');
 $receipt=['status'=>'applied_PASS','changed'=>$changes,'all_other_web_files_preserved'=>true,'original_private_files_preserved'=>true,'database_writes'=>false,'time'=>gmdate('c'),'backup'=>basename($backup)];file_put_contents($backup.'/receipt.json',json_encode($receipt));chmod($backup.'/receipt.json',0600);echo json_encode($receipt);
}catch(Throwable $e){foreach(array_reverse($written) as $p)if(hash_file('sha256',$root.'/'.$p)===$payload[$p]['candidate_sha256'])copy($backup.'/'.str_replace('/','__',$p),$root.'/'.$p);throw $e;}
